"""API-facing models for packs, modules, example data, sign-up providers and the second-factor status (job CK). Mirrors packages/contracts/packs.schema.json (generated by `make contracts`).

A pack is DATA (packages/packs/<id>/pack.json). These models carry what a screen needs; no code reads a pack id (modules are the only extension point)."""

from __future__ import annotations

import uuid
from datetime import datetime
from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, StringConstraints

PackStatus = Literal["draft", "preview", "published"]
PackSource = Literal["signup", "default", "legacy", "operator"]
LanguageReview = Literal["draft", "web_dictionary", "native_reviewed"]
PackCode = Annotated[str, StringConstraints(pattern=r"^[a-z][a-z0-9_]{1,30}$")]


class _Out(BaseModel):
    model_config = ConfigDict(extra="forbid")


class PackSummaryOut(_Out):
    """One business type as the sign-up card shows it (GET /v1/packs, no sign-in)."""

    pack_id: str
    version: int
    status: PackStatus
    # true only when a real owner of this kind of business reviewed the pack; false means the screens show "Not validated by a real owner yet"
    validated: bool
    names: dict[str, str]
    summary: dict[str, str]
    accent: str
    owl_prop: str


class PackListOut(_Out):
    packs: list[PackSummaryOut]


class ModuleStateOut(_Out):
    module: str
    enabled: bool
    # why: `pack` (the business type's pack lists it) or `core` (Lead Desk: on for every business); plan entitlements and operator overrides will add reasons (ADR 0084 part 6)
    reason: Literal["pack", "core"]


class WorkspaceModulesOut(_Out):
    modules: list[ModuleStateOut]


class WorkspacePackOut(_Out):
    """GET /v1/tenants/{id}/pack: the pack this business runs, pinned to the version it chose."""

    pack_id: str
    version: int
    status: PackStatus
    validated: bool
    source: PackSource
    chosen_at: datetime
    names: dict[str, str]
    summary: dict[str, str]
    accent: str
    owl_prop: str
    # the module whose phone tab is the pack's core work
    core_tab: str
    modules: list[str]
    units: list[str]
    default_unit: str | None
    # language -> label key -> word. English carries every key; the other languages may be partial and fall back to English per key.
    labels: dict[str, dict[str, str]]
    language_review: dict[str, LanguageReview]
    # does the pack ship example data? A pack with none loads an empty batch, so the web does not offer the button (it is still shown while a sample is loaded, to remove it)
    has_example_data: bool


class ExampleCountsOut(_Out):
    companies: int
    contacts: int
    leads: int
    products: int


class ExampleDataStatusOut(_Out):
    """GET/POST /v1/tenants/{id}/example-data: is the labelled sample loaded."""

    loaded: bool
    batch_id: uuid.UUID | None
    pack_id: str | None
    loaded_at: datetime | None
    removed_at: datetime | None
    counts: ExampleCountsOut


class ExampleDataRemoveOut(_Out):
    """DELETE /v1/tenants/{id}/example-data: what was removed, and what was KEPT because it was changed or is in use."""

    batch_id: uuid.UUID | None
    removed: ExampleCountsOut
    kept: ExampleCountsOut


class AuthProvidersOut(_Out):
    """GET /v1/auth/providers (no sign-in): which ways to sign up this system offers. A provider is on only when its keys are configured (env); e-mail is always on."""

    email: Literal[True]
    google: bool
    facebook: bool


class AccountSecurityOut(_Out):
    """GET /v1/account/security: where the second factor stands for this session. It is NOT asked at sign-up; it is asked at the first action that needs one."""

    session_level: Literal["aal1", "aal2"]
    asked_at_sign_up: Literal[False]
    # the groups of actions that need an aal2 session for an Owner or Admin (the database refuses them otherwise, SM306)
    needed_for: list[Literal["approvals", "whatsapp_connect", "rules_and_prices", "imports_and_exports", "team_and_privacy"]]
